"""Rebuild 96 original Structure 2 questions using standard-library helpers."""
from structure_common import *

b=Bank(2)

# S2.1: charge balance, electron transfer, bulk properties and lattice reasoning.
salts=[('Mg','2+','N','3-','Mg3N2',['MgN','Mg2N3','Mg3N']),('Al','3+','O','2-','Al2O3',['AlO','Al3O2','AlO3']),('Ca','2+','P','3-','Ca3P2',['CaP','Ca2P3','CaP2']),('Na','+','S','2-','Na2S',['NaS','NaS2','Na2S2'])]
for v,(cat,cc,an,ac,answer,wrong) in enumerate(salts,1):
    b.add('S21-charge-balance','S2.1',v,'Formula of an ionic compound',f'An ionic compound contains {c(cat,cc)} and {c(an,ac)} ions. What is its simplest formula?',options=[c(answer)]+[c(x) for x in wrong],reason=f'The smallest whole-number ratio that makes the total positive and negative charges equal gives {c(answer)}.')

transfers=[('Li','F',3,9,1,r'1s^{2}',r'1s^{2}2s^{2}2p^{6}','LiF'),('Na','Cl',11,17,1,r'1s^{2}2s^{2}2p^{6}',r'1s^{2}2s^{2}2p^{6}3s^{2}3p^{6}','NaCl'),('Mg','O',12,8,2,r'1s^{2}2s^{2}2p^{6}',r'1s^{2}2s^{2}2p^{6}','MgO'),('Ca','S',20,16,2,r'[Ar]',r'[Ar]','CaS')]
for v,(metal,non,z1,z2,e,cf1,cf2,formula) in enumerate(transfers,1):
    cp=('+' if e==1 else str(e)+'+');cm=('-' if e==1 else str(e)+'-')
    b.add('S21-electron-transfer','S2.1',v,'Forming a simple ionic compound',f'The element {c(metal)} (atomic number {z1}) reacts with {c(non)} (atomic number {z2}) to form {c(formula)}.',parts=[P('Describe electron transfer and state the ions formed.',A(f'Each {c(metal)} atom loses {e} electron'+('s' if e>1 else '')+f', forming {c(metal,cp)}.'),A(f'Each {c(non)} atom gains {e} electron'+('s' if e>1 else '')+f', forming {c(non,cm)}.')),P('Write the ground-state electron configuration of each ion.',A(c(metal,cp)+': '+m(cf1)+'; '+c(non,cm)+': '+m(cf2)+'.')),P('State the force that holds the ionic solid together.',A('Electrostatic attraction acts between oppositely charged ions throughout a three-dimensional lattice.'))])

for v,(solid,molten,water,label) in enumerate([('negligible','high','high','A'),('negligible','high','high','B'),('negligible','high','not tested','C'),('negligible','high','high','D')],1):
    b.add('S21-conductivity','S2.1',v,'Interpreting conductivity evidence',f'A constructed test of substance {label} gives the following electrical conductivities. The substance melts without decomposing; where an aqueous test is reported it dissolves without reacting.'+table(['Condition','Conductivity'],[('solid',solid),('molten',molten),('aqueous solution',water)]),options=['An ionic lattice with mobile ions after melting.','A molecular solid containing only neutral molecules.','A metal whose delocalized electrons cannot move in the solid.','A covalent network with electrons fixed in every bond.'],reason='Ions are fixed in the solid but become mobile in a melt; mobile charged particles carry the current. The combination of observations is characteristic of an ionic compound.')

comparisons=[('NaF','NaI','Both compounds contain ions with charges +1 and −1. The fluoride ion is smaller than the iodide ion.','NaF','The smaller separation between oppositely charged ions gives stronger electrostatic attraction.'),('MgO','NaF','The ions in magnesium oxide have charges +2 and −2, while those in sodium fluoride have charges +1 and −1. Their interionic distances are similar for this comparison.','MgO','The greater product of ionic charges gives stronger electrostatic attraction.'),('LiCl','KCl','Both compounds contain ions with charges +1 and −1. The lithium ion is smaller than the potassium ion.','LiCl','The smaller interionic separation gives stronger electrostatic attraction.'),('CaO','BaO','Both compounds contain ions with charges +2 and −2. The calcium ion is smaller than the barium ion.','CaO','The smaller interionic separation gives stronger electrostatic attraction.')]
for v,(x,y,data,ans,why) in enumerate(comparisons,1):
    b.add('S21-lattice-strength','S2.1',v,'Comparing ionic attractions',f'Compare {c(x)} and {c(y)}. {data} Use a simple electrostatic lattice model.',parts=[P('Predict which compound has the greater magnitude of lattice enthalpy and explain your choice.',A(c(ans)+'.'),Rn(why)),P('Explain why a melting-point prediction based only on this model should be described as a trend rather than an exact calculation.',Rn('The simplified comparison does not include the detailed crystal structure, packing and all interactions in the real solid, so it cannot determine an exact temperature.'))])

for v,(crystal,event) in enumerate([('sodium chloride','a hammer strikes a crystal'),('potassium bromide','a crystal is squeezed unevenly'),('magnesium oxide','a shear force displaces one plane of ions'),('calcium fluoride','an indentation causes neighbouring planes to shift')],1):
    b.add('S21-brittleness','S2.1',v,'Why an ionic crystal fractures',f'A solid {crystal} sample fractures when {event}.',parts=[P('Explain the fracture in terms of the ionic lattice.',Rn('Displacement brings ions of the same charge into close alignment across a plane.'),Rn('Electrostatic repulsion between like charges separates the planes and the crystal fractures.')),P('Explain why the undisturbed solid does not conduct electricity even though it contains charged ions.',Rn('The ions are fixed in lattice positions and cannot move through the solid to transport charge.'))])

ionfacts=[('Why is solid sodium chloride described by a formula unit rather than by separate sodium chloride molecules?','Its ions belong to an extended lattice without discrete NaCl molecules.',['Every sodium ion bonds only to one chloride ion.','The solid contains neutral sodium atoms and chlorine molecules.','A formula unit must contain exactly one electron.'],'The formula gives the simplest ion ratio in the extended lattice.'),
('A metal atom forms a cation by losing its outermost electron. Why is the cation generally smaller than the atom?','The remaining electrons experience stronger effective attraction and the outer shell may be lost.',['The nucleus loses a proton.','The remaining electrons repel one another more strongly because there are more of them.','The proton radius doubles.'],'Removing electrons reduces electron-electron repulsion and may remove the outer shell; nuclear charge is unchanged.'),
('A non-metal atom gains an electron to form an anion. Why is the anion generally larger?','Increased electron-electron repulsion expands the electron cloud.',['The nucleus gains a neutron for each electron.','The number of protons increases.','All electrons enter a new principal shell.'],'The same nuclear charge attracts more electrons, increasing repulsion and reducing attraction per electron.'),
('What does a line between ions in a simplified lattice drawing usually represent?','A visual indication of arrangement or attraction, rather than one localized electron-pair bond.',['A pair of electrons shared only by those two ions.','A molecule formed from every connected pair.','The path followed by a stationary ion.'],'Ionic bonding is electrostatic and acts in all directions through the lattice; it is not represented by localized covalent electron pairs.')]
for v,(stem,ans,wrong,reason) in enumerate(ionfacts,1):
    b.add('S21-ionic-model-limits','S2.1',v,'Using the ionic model',stem,options=[ans]+wrong,reason=reason)

# S2.2: shared Lewis/VSEPR/IMF/chromatography; extensions explicitly AHL.
lewisitems=[('NH3','N',[('H',1,0)]*3,1,8,'trigonal pyramidal','about 107°','polar','Three N–H bond dipoles do not cancel in the trigonal pyramidal geometry.'),('H2O','O',[('H',1,0)]*2,2,8,'bent','about 104.5°','polar','The two O–H bond dipoles do not cancel in the bent geometry.'),('CO2','C',[('O',2,2)]*2,0,16,'linear','180°','non-polar','Equal C=O bond dipoles act in opposite directions and cancel.'),('CH4','C',[('H',1,0)]*4,0,8,'tetrahedral','109.5°','non-polar','The four equal C–H bond dipoles cancel by tetrahedral symmetry.')]
for v,(formula,centre,terms,lp,ve,shape,angle,polarity,why) in enumerate(lewisitems,1):
    if v==4:
        b.add('S22-lewis-and-shape','S2.2',v,'A coordinate bond in ammonium',f'Ammonia, {c("NH3")}, reacts with a proton, {c("H","+")}, to form {c("NH4","+")}.',parts=[P('Draw the Lewis structure of the ammonium ion, including its overall charge.',A('There are four single N–H bonds and no lone pair on nitrogen, using eight valence electrons in total.'),A('The whole structure is enclosed in brackets with an overall + charge.')),P('State the shape and bond angle of the ion.',A('Tetrahedral; 109.5°.')),P('Explain how a coordinate covalent bond forms in this reaction.',A('The nitrogen atom donates its lone pair to the proton.'),Rn('Both bonding electrons initially come from nitrogen. After formation the four N–H bonds are equivalent.'))],worked=lewis('N',[('H',1,0)]*4,charge='+'))
        continue
    b.add('S22-lewis-and-shape','S2.2',v,'From electrons to molecular shape',f'Consider a molecule of {c(formula)}. Use the usual valence electron counts H = 1, C = 4, N = 5 and O = 6.',parts=[P('Draw a Lewis structure showing all bonds and lone pairs.',A(f'The structure uses {ve} valence electrons and the correct bond orders.'),A(f'There are {lp} lone pair'+('s' if lp!=1 else '')+' on the central atom; any oxygen terminal atom has two lone pairs.')),P('State the molecular shape and approximate bond angle.',A(f'{shape.capitalize()}; {angle}.')),P('Classify the molecule as polar or non-polar and explain.',A(f'The molecule is {polarity}.'),Rn(why))],worked=lewis(centre,terms,lp))
    if formula=='CO2':
        q=b.questions[-1]
        q['parts'].append({'label':'d','prompt':'Compare a carbon-oxygen double bond with a carbon-oxygen single bond in otherwise comparable molecular environments.','marks':2})
        q['markScheme'].append({'part':'d','steps':[{'code':'A1','text':'The double bond is generally shorter.'},{'code':'A1','text':'The double bond is generally stronger and requires more energy to break.'}]})
        q['marks']+=2

forces=[('ethanol','dimethyl ether','Both have molecular formula C2H6O. Ethanol has an O–H bond; dimethyl ether has no O–H bond.','ethanol','Ethanol molecules can hydrogen-bond to one another; dimethyl ether molecules cannot donate hydrogen bonds to one another.'),('butane','propane','Both molecules are non-polar, with similar shapes. Butane has more electrons and a larger electron cloud.','butane','Butane has stronger London dispersion forces because its larger electron cloud is more polarizable.'),('propan-1-ol','propane','Propan-1-ol contains a hydroxy group; propane contains only carbon and hydrogen.','propan-1-ol','Propan-1-ol can form hydrogen bonds with water; propane interacts with water mainly through much weaker dispersion forces.'),('hydrogen fluoride','hydrogen chloride','Both are small polar molecules. Fluorine is particularly electronegative and small.','hydrogen fluoride','Hydrogen fluoride forms strong intermolecular hydrogen bonds; hydrogen chloride is not normally classified as hydrogen-bonding in this model.')]
for v,(x,y,info,ans,why) in enumerate(forces,1):
    solubility=v==3;prop='is more soluble in water' if solubility else 'has the higher boiling point'
    b.add('S22-intermolecular','S2.2',v,'Comparing intermolecular forces',f'Compare {x} and {y}. {info}',parts=[P(f'Predict which substance {prop} and explain in terms of intermolecular forces.',A(ans.capitalize()+'.'),Rn(why)),P('Distinguish an intermolecular force from an intramolecular covalent bond.',A('An intermolecular force acts between separate molecules; a covalent bond is attraction between a shared electron pair and the nuclei within a molecule.'))])

for v,(front,dist1,dist2) in enumerate([(80,32,56),(100,25,70),(90,27,63),(120,48,90)],1):
    rf1=dist1/front;rf2=dist2/front
    b.add('S22-chromatography','S2.2',v,'Quantifying a chromatogram',f'In a constructed chromatography experiment, the solvent front travels {front:.1f} mm from the baseline. Spots A and B travel {dist1:.1f} mm and {dist2:.1f} mm. The stationary phase is polar and the mobile phase is less polar. The compounds are compared under identical conditions.',kind='data-based',diagram=chromatography([dist1,dist2],front),parts=[P('Calculate the retention factor of each compound.',M(m(r'R_{\mathrm f}=\text{distance moved by solute}/\text{distance moved by solvent front}')+'.'),A(f'A: {rf1:.3f}; B: {rf2:.3f}. Both ratios are dimensionless.')),P('Which compound is more strongly retained by the stationary phase? Explain.',A('Compound A.'),Rn('Its smaller retention factor means it spends a greater fraction of time associated with the stationary phase under these conditions.')),P('Explain why a retention factor alone does not prove the identity of an unknown.',Rn('Different compounds may have the same retention factor; a reference under identical conditions and additional evidence are needed.'))])

resonance=[('NO3','-','N',[('O',2,2),('O−',1,3),('O−',1,3)],0,24,1,'The central N has formal charge +1; each singly bonded O has −1; the doubly bonded O has 0.','Three equivalent contributors place the double bond on each oxygen in turn.'),('CO3','2-','C',[('O',2,2),('O−',1,3),('O−',1,3)],0,24,0,'The central C has formal charge 0; each singly bonded O has −1; the doubly bonded O has 0.','Three equivalent contributors place the double bond on each oxygen in turn.'),('O3','','O',[('O',2,2),('O−',1,3)],1,18,1,'The central O has formal charge +1; the singly bonded terminal O has −1; the doubly bonded terminal O has 0.','Two equivalent contributors interchange the single and double bonds.'),('NO2','-','N',[('O',2,2),('O−',1,3)],1,18,0,'The central N has formal charge 0; the singly bonded O has −1; the doubly bonded O has 0.','Two equivalent contributors interchange the single and double bonds.')]
for v,(formula,ch,center,terms,lp,e,fc,charges,contributors) in enumerate(resonance,1):
    if v==4:
        b.add('S22-resonance-charge','S2.2',v,'Bond lengths in benzene',f'Benzene has molecular formula {c("C6H6")}. All six carbon-carbon bonds have the same length. A localized model with alternating single and double bonds would predict two different lengths.',level='ahl',parts=[P('Explain the equal carbon-carbon bond lengths using electron delocalization.',A('Each carbon contributes one electron in a p orbital perpendicular to the ring.'),Rn('The p orbitals overlap around the ring to form a delocalized pi system involving six electrons.'),Rn('All six carbon-carbon bonds are equivalent, with bond order intermediate between single and double.')),P('Draw a representation that shows all six carbon atoms, all six hydrogens, and the delocalized ring bonding.',A('A six-carbon ring with one hydrogen per carbon and a circle representing the delocalized pi bonding; all carbon-hydrogen bonds are single.'))],worked=benzene_svg())
        continue
    cp=center+('+' if fc==1 else '')
    b.add('S22-resonance-charge','S2.2',v,'Formal charge and delocalization',f'Consider {c(formula,ch)}. A Lewis contributor contains one central {center} atom, one double bond to oxygen and single bonds to the other oxygen atom'+('s' if len(terms)>2 else '')+f'. The central atom has {lp} lone pair'+('s' if lp!=1 else '')+'. Each terminal oxygen completes an octet.',level='ahl',parts=[P('Calculate the formal charge of the central atom and identify the formal charges on the terminal oxygen atoms.',M(m(r'\mathrm{FC}=\text{valence electrons}-\text{nonbonding electrons}-\tfrac12\text{bonding electrons}')+'.'),A(charges)),P('Explain why the measured central-oxygen bonds have equal lengths, rather than separate single- and double-bond lengths.',A(contributors),Rn('The actual bonding is delocalized; the equivalent bonds have the same intermediate bond order. The ion or molecule does not switch between localized structures.'))],worked=lewis(cp,terms,lp,ch.replace('2-','2−').replace('-','−')))

geometries=[('PF5',5,0,'trigonal bipyramidal','90°, 120° and 180°','non-polar','The five bond dipoles cancel in the symmetric trigonal bipyramidal arrangement.'),('SF6',6,0,'octahedral','90° and 180°','non-polar','The six equal bond dipoles cancel in the symmetric octahedral arrangement.'),('SF4',5,1,'seesaw','less than 90° and less than 120° for adjacent bonds; the axial angle is slightly less than 180°','polar','An equatorial lone pair makes the bond-dipole arrangement asymmetric.'),('XeF4',6,2,'square planar','90° and 180°','non-polar','The two lone pairs occupy opposite positions; the four equal Xe–F bond dipoles cancel in the square plane.')]
for v,(formula,domains,lp,shape,angles,polarity,why) in enumerate(geometries,1):
    b.add('S22-extended-vsepr','S2.2',v,'More than four electron domains',f'In {c(formula)}, the central atom has {domains} electron domains, including {lp} lone pair'+('s' if lp!=1 else '')+'. Each fluorine is joined by one single bond.',level='ahl',parts=[P('State the molecular shape and its characteristic bond angles.',A(shape.capitalize()+'.'),A(angles+'.')),P('Use electron-domain repulsion to explain the arrangement of any lone pairs, or the symmetry if no lone pairs are present.',Rn('Electron domains arrange to minimize repulsion; '+('an equatorial position gives a lone pair fewer 90° interactions.' if formula=='SF4' else 'the two lone pairs occupy opposite octahedral positions.' if formula=='XeF4' else 'identical bonding domains are arranged symmetrically.'))),P('Predict the molecular polarity and explain.',A('The molecule is '+polarity+'.'),Rn(why))])

hybrids=[('ethene',['CH₂','CH₂'],[2],(),5,1,'Both carbon atoms are sp² hybridized.','Each carbon has three sigma-bonding directions and one unhybridized p orbital.'),('ethyne',['CH','CH'],[3],(),3,2,'Both carbon atoms are sp hybridized.','Each carbon has two sigma-bonding directions and two unhybridized p orbitals.'),('ethanal',['CH₃','C','H'],[1,1],(1,),6,1,'The methyl carbon is sp³; the carbonyl carbon is sp².','The methyl carbon has four sigma-bonding directions, while the carbonyl carbon has three and one unhybridized p orbital.'),('ethanenitrile',['CH₃','C','N'],[1,3],(),5,2,'The methyl carbon is sp³; the nitrile carbon is sp.','The methyl carbon has four sigma-bonding directions, while the nitrile carbon has two and two unhybridized p orbitals.')]
for v,(name,labels,orders,carbonyls,sigma,pi,hyb,why) in enumerate(hybrids,1):
    b.add('S22-sigma-pi-hybridization','S2.2',v,'Sigma and pi bonding',f'The diagram shows a condensed structural formula of {name}. Count all bonds, including C–H bonds represented by the condensed groups.',level='ahl',diagram=chain_svg(labels,orders,carbonyls),parts=[P('State the total numbers of sigma and pi bonds in one molecule.',A(f'{sigma} sigma bonds.'),A(f'{pi} pi bond'+('s.' if pi!=1 else '.'))),P('State the hybridization of each distinct carbon environment and explain.',A(hyb),Rn(why)),P('Explain how a pi bond forms.',A('A pi bond forms by sideways overlap of parallel unhybridized p orbitals, with electron density above and below the sigma-bond axis.'))])

# S2.3: model and properties, followed by genuine d-orbital extension.
metalmodels=[('What holds a pure metal lattice together?','Attraction between positive metal ions and delocalized electrons.',['Attraction between neutral molecules through hydrogen bonds.','Repulsion between adjacent positive ions.','Electron pairs localized between one fixed pair of atoms only.'],'Metallic bonding is electrostatic attraction between the positive ion lattice and mobile delocalized electrons.'),('Which particles transport charge through a solid metal?','Delocalized electrons.',['Positive ions moving from one end of the solid to the other.','Neutral metal molecules.','Neutrons released from nuclei.'],'The ions remain in lattice positions; delocalized electrons can move through the solid.'),('Why can a molten pure metal conduct electricity?','Delocalized electrons remain mobile in the liquid.',['Every metal ion becomes a neutral molecule.','Only neutrons carry charge in a liquid.','The liquid contains no charged particles.'],'Metallic electron delocalization and mobile charge carriers persist after melting.'),('Which feature of metallic bonding helps a metal be drawn into a wire?','The attraction is not limited to fixed directional pairs of atoms.',['Each atom can bond only to one neighbour.','The lattice consists of separated molecules.','All electron motion stops when the metal is stretched.'],'Non-directional attraction can persist as positive ion layers change their relative positions.')]
for v,(stem,ans,wrong,why) in enumerate(metalmodels,1):
    b.add('S23-metallic-model','S2.3',v,'The metallic model',stem,options=[ans]+wrong,reason=why)

for v,(metal,context) in enumerate([('copper','a low-voltage electrical wire'),('aluminium','a conducting strip in a circuit'),('silver','an electrical contact'),('magnesium','a clean metal ribbon used as a conductor')],1):
    b.add('S23-mobile-electrons','S2.3',v,'Charge and heat transfer in a metal',f'A sample of {metal} is used as {context}. It also transfers thermal energy effectively.',parts=[P('Explain its electrical conductivity in terms of its bonding model.',A('The solid contains delocalized electrons.'),Rn('These mobile charged particles drift through the lattice under an applied potential difference.')),P('Explain one role of electrons in thermal conduction.',Rn('Electrons with higher energy transfer energy through collisions and interactions across the metal; energy moves from the hotter to the colder region.')),P('State whether the positive metal ions must migrate through the solid for the current to flow.',A('No. The positive ions remain associated with lattice positions while the electrons transport charge.'))])

for v,(metal,operation) in enumerate([('aluminium','rolled into a thin sheet'),('copper','drawn into a narrow wire'),('gold','hammered into thin foil'),('silver','pressed into a curved ornament')],1):
    b.add('S23-deformation','S2.3',v,'Deforming a metal',f'A piece of pure {metal} is {operation} without crumbling.',parts=[P('Explain this behaviour using the metallic bonding model.',Rn('Layers of positive metal ions can slide or change positions.'),Rn('Attraction to the delocalized electrons persists, so bonding is maintained despite the change of shape.')),P('Explain why an equivalent displacement often fractures an ionic crystal.',Rn('The displacement can place like-charged ions next to one another, causing repulsion and fracture.'))])

metalcomparisons=[('sodium','magnesium','The effective positive ion charge and the number of delocalized electrons per atom are greater in magnesium; its ions are also smaller.','magnesium'),('magnesium','aluminium','The simple model assigns three delocalized electrons per aluminium atom and two per magnesium atom; aluminium ions are smaller.','aluminium'),('potassium','sodium','Both contribute one outer electron per atom, but potassium ions are larger.','sodium'),('calcium','magnesium','Both contribute two outer electrons per atom, but calcium ions are larger.','magnesium')]
for v,(x,y,info,ans) in enumerate(metalcomparisons,1):
    b.add('S23-main-group-strength','S2.3',v,'Comparing metallic attraction',f'Compare {x} and {y} using a simple metallic bonding model. {info}',parts=[P('Predict which has stronger metallic bonding and explain using the stated information.',A(ans.capitalize()+'.'),Rn('A greater density of charge and/or smaller ion-electron separation gives stronger electrostatic attraction.')),P('State why this alone does not calculate an exact melting temperature.',Rn('Real solids also differ in crystal structure, packing and other factors omitted from the simplified bonding model, so it predicts a broad trend rather than an exact temperature.'))])

for v,(metal,conf) in enumerate([('titanium',r'[Ar]3d^{2}4s^{2}'),('vanadium',r'[Ar]3d^{3}4s^{2}'),('iron',r'[Ar]3d^{6}4s^{2}'),('nickel',r'[Ar]3d^{8}4s^{2}')],1):
    b.add('S23-d-orbital-extension','S2.3',v,'Transition-metal bonding',f'An isolated {metal} atom has ground-state configuration {m(conf)}. Which explanation best extends the simple metallic bonding model to the solid?',level='ahl',options=['Electrons associated with both the outer s and d orbitals can contribute to metallic bonding.','Only the deepest 1s electrons can participate in metallic bonding.','The metal must consist of discrete diatomic molecules.','Every d electron must remain permanently localized on one isolated atom.'],reason='The energies and overlap of the valence s and d orbitals allow both types to contribute to the delocalized bonding in transition metals; the isolated-atom configuration does not describe the solid as separate atoms.')

for v,(metal,application) in enumerate([('tungsten','a component exposed to a high operating temperature'),('chromium','a hard metallic component'),('molybdenum','a heat-resistant part'),('tantalum','a component that must resist melting')],1):
    b.add('S23-transition-cohesion','S2.3',v,'Why many transition metals are strongly bonded',f'A materials discussion proposes {metal} for {application}. Treat this as a qualitative bonding question, without requiring numerical property values.',level='ahl',parts=[P('Explain why transition metals often have stronger metallic bonding than group 1 metals.',A('Valence d electrons as well as s electrons can contribute to metallic bonding.'),Rn('The resulting greater contribution of delocalized valence electrons can strengthen attraction between the positive metal lattice and the electron density.')),P('Explain why counting nominal valence electrons alone cannot predict the melting-point order of every transition metal.',Rn('The extent of orbital overlap, electron occupation, crystal structure and the entropy of melting also differ, so a simple electron count is incomplete.'))])

# S2.4: bonding continuum, alloys, networks, and addition/condensation polymers.
for v,(x,y,enx,eny,ans) in enumerate([('Na','Cl',0.9,3.2,'ionic'),('C','H',2.6,2.2,'covalent'),('Mg','Al',1.3,1.6,'metallic'),('O','H',3.4,2.2,'covalent')],1):
    mean=(enx+eny)/2;diff=abs(enx-eny)
    b.add('S24-bonding-triangle','S2.4',v,'Coordinates on a bonding triangle',f'On a bonding triangle, the horizontal coordinate is the mean electronegativity and the vertical coordinate is the electronegativity difference. Use the supplied values: {x} = {enx:.1f}, {y} = {eny:.1f}. Which coordinate pair describes an interaction between these elements?',options=[f'({mean:.2f}, {diff:.2f})',f'({diff:.2f}, {mean:.2f})',f'({enx+eny:.2f}, {diff:.2f})',f'({mean:.2f}, {enx+eny:.2f})'],reason=f'Mean = ({enx:.1f} + {eny:.1f})/2 = {mean:.2f}; difference = |{enx:.1f} − {eny:.1f}| = {diff:.2f}. The triangle treats bonding as a continuum rather than a sharp classification boundary.')

alloys=[('brass','copper and zinc','zinc atoms replace some copper atoms'),('bronze','copper and tin','tin atoms replace some copper atoms'),('an aluminium-magnesium alloy','aluminium and magnesium','magnesium atoms replace some aluminium atoms'),('steel','iron and a small amount of carbon','small carbon atoms occupy some spaces in the iron lattice')]
for v,(name,components,change) in enumerate(alloys,1):
    b.add('S24-alloys','S2.4',v,'Changing a metal’s mechanical properties',f'A sample of {name} contains {components}. In a simplified model, {change}.',parts=[P('Explain why the alloy is often harder than the pure host metal.',Rn('The added atoms distort the regular arrangement of the host lattice.'),Rn('This makes the movement of layers or dislocations more difficult, so a greater force is needed for deformation.')),P('Explain why the alloy can still conduct electricity.',A('It retains mobile delocalized electrons.')),P('Classify this alloy as a compound or a mixture and justify your answer.',A('It is a mixture: its composition need not be a fixed whole-number stoichiometric ratio.'))])

materials=[('diamond','very hard, electrical insulator','Each carbon has four covalent bonds in a three-dimensional network.','Strong directional bonds extend throughout the network, resisting deformation.','All valence electrons are involved in localized bonding, so there are no freely mobile charge carriers.'),('graphite','soft between layers, conducts electricity along layers','Each carbon has three covalent bonds in a planar network, with one electron contributing to delocalization.','Layers are held together by relatively weak dispersion forces and can slide over one another.','Delocalized electrons can move along the layers and transport charge.'),('silicon dioxide','hard, high melting point, electrical insulator','Each silicon is covalently bonded to four oxygen atoms, and each oxygen links two silicon atoms in a network.','Many strong covalent bonds must be disrupted to melt the extended network.','The structure lacks freely mobile charged particles.'),('graphene','strong in its plane and electrically conducting','A single sheet contains carbon atoms each bonded to three neighbours, with delocalized electrons.','Strong carbon-carbon covalent bonds extend across the sheet.','Delocalized electrons move across the sheet and carry charge.')]
for v,(name,props,structure,mechanical,electrical) in enumerate(materials,1):
    b.add('S24-network-materials','S2.4',v,'Structure and material properties',f'A materials card describes {name} as {props}. {structure}',parts=[P('Explain the stated mechanical or melting property in terms of the structure.',Rn(mechanical)),P('Explain the electrical behaviour.',Rn(electrical)),P('Explain why it is inappropriate to describe a piece of this material as a collection of small separate molecules.',A('Covalent bonding extends through a continuous network or sheet; there are no discrete molecular units containing only a few atoms.'))])

additions=[('ethene',['CH₂','CH₂'],['CH₂','CH₂'],'No atom is eliminated; the carbon-carbon double bond becomes a single bond in the chain.'),('propene',['CH₂','CH(CH₃)'],['CH₂','CH(CH₃)'],'The methyl side group remains attached to alternate backbone carbons; the double bond opens.'),('chloroethene',['CH₂','CHCl'],['CH₂','CHCl'],'The chlorine remains attached to a backbone carbon; the double bond opens.'),('tetrafluoroethene',['CF₂','CF₂'],['CF₂','CF₂'],'All four fluorine atoms remain in each repeat unit; the double bond opens.')]
for v,(name,monomer,repeat,why) in enumerate(additions,1):
    b.add('S24-addition-polymer','S2.4',v,'Constructing an addition-polymer repeat unit',f'The diagram shows the monomer {name}. It undergoes addition polymerization without rearrangement.',diagram=chain_svg(monomer,[2]),parts=[P('Draw the polymer repeat unit with brackets, continuation bonds and n.',A('The two alkene carbons form a single-bonded backbone.'),A('All substituents and atom counts are retained; two continuation bonds cross the brackets and n is shown.')),P('Explain why no small molecule is released.',Rn(why)),P('Describe how the bonding between carbon atoms changes during addition polymerization.',A('Each monomer carbon-carbon double bond becomes a single bond, and new single covalent bonds link neighbouring monomer residues.'))],worked=chain_svg(repeat,[1],repeat=True))

for v,(a,d) in enumerate([(2,2),(3,2),(2,4),(4,3)],1):
    formula=f'C{a+d+2}H{2*a+2*d}O4'
    b.add('S24-polyester','S2.4',v,'Building a polyester',f'A polyester is made from the diol {c(f'HO(CH2){a}OH')} and the dicarboxylic acid {c(f'HOOC(CH2){d}COOH')}. Assume a linear polymer and ignore end groups when describing a repeat unit.',level='ahl',parts=[P('Draw one repeat unit showing the ester links and continuation bonds.',A('A diol residue and a diacid residue are joined through two ester links in the repeat unit.'),A('The repeat structure has correct carbonyl bonds, atom counts, brackets and continuation bonds.')),P('State the small molecule released when each ester link forms and identify the functional groups that react.',A('Water is released; a hydroxy group of the diol reacts with a carboxyl group of the diacid.')),P('Deduce the molecular formula of one repeat unit, ignoring end groups.',M('Add the formulae of one diol and one diacid, then subtract two water molecules.'),A(c(formula)+'.'))],worked=chain_svg(['O',f'(CH₂){str(a).translate(str.maketrans("0123456789","₀₁₂₃₄₅₆₇₈₉"))}','O','C',f'(CH₂){str(d).translate(str.maketrans("0123456789","₀₁₂₃₄₅₆₇₈₉"))}','C'],carbonyls=(3,5),repeat=True))

for v,(a,d) in enumerate([(2,4),(4,4),(6,4),(3,2)],1):
    formula=f'C{a+d+2}H{2*a+2*d+2}N2O2'
    b.add('S24-polyamide','S2.4',v,'Building a polyamide',f'A polyamide is made from the diamine {c(f'H2N(CH2){a}NH2')} and the dicarboxylic acid {c(f'HOOC(CH2){d}COOH')}. Assume a linear polymer and ignore end groups when describing a repeat unit.',level='ahl',parts=[P('Draw one repeat unit showing the amide links and continuation bonds.',A('The diamine and diacid residues are joined through amide links containing C(=O)–NH.'),A('The repeat has correct carbonyl bonds, retained N–H bonds, atom counts and continuation bonds.')),P('State the small molecule released when each amide link forms.',A('Water.')),P('Determine the formula of one repeat unit, ignoring end groups.',M('Add one diamine and one diacid formula and subtract two water molecules.'),A(c(formula)+'.'))],worked=chain_svg(['NH',f'(CH₂){str(a).translate(str.maketrans("0123456789","₀₁₂₃₄₅₆₇₈₉"))}','NH','C',f'(CH₂){str(d).translate(str.maketrans("0123456789","₀₁₂₃₄₅₆₇₈₉"))}','C'],carbonyls=(3,5),repeat=True))

b.extend(5,P('Give the formula, including charge, of the ammonium ion and the hydroxide ion.',A('Ammonium: '+c('NH4','+')+'.'),A('Hydroxide: '+c('OH','-')+'.')))
b.extend(6,P('Give the formula, including charge, of the nitrate ion and the hydrogencarbonate ion.',A('Nitrate: '+c('NO3','-')+'.'),A('Hydrogencarbonate: '+c('HCO3','-')+'.')))
b.extend(7,P('Give the formula, including charge, of the carbonate ion and the sulfate ion.',A('Carbonate: '+c('CO3','2-')+'.'),A('Sulfate: '+c('SO4','2-')+'.')))
b.extend(8,P('Give the formula of the phosphate ion, then deduce the formula of ammonium phosphate. The ammonium ion is '+c('NH4','+')+'.',A('Phosphate: '+c('PO4','3-')+'.'),A('Ammonium phosphate: '+c('(NH4)3PO4')+'; three ammonium ions balance one phosphate ion.')))
b.extend(26,P('Compare water with '+c('BF3')+'. Boron has three valence electrons. In the usual Lewis model for '+c('BF3')+', state the number of electrons around boron, its molecular shape and bond angle.',A('Boron is surrounded by six bonding electrons, so it is electron-deficient and has an incomplete octet.'),A('Trigonal planar.'),A('120°.')))
b.extend(85,P('Explain why poly(ethene) can soften when heated even though its backbone contains strong covalent bonds.',Rn('Heating permits the long chains to move past one another by overcoming relatively weak attractions between chains.'),Rn('Softening does not require breaking the strong carbon-carbon covalent bonds along the backbone.')))
b.extend(93,P('Explain how amide groups can strengthen attractions between polyamide chains.',A('N–H groups can donate hydrogen bonds to carbonyl oxygen atoms on neighbouring chains.'),Rn('These intermolecular hydrogen bonds oppose separation or sliding of the chains, increasing cohesion compared with otherwise similar chains without such interactions.')))
